const rows = queries.fetchApps.data?.rows || [];
const tiles = rows.map(row => `
  <article onclick="window.parent.postMessage({type:'tile_click',appId:'${row.tj_app_id}',name:'${row.name}'},'*')"
    style="min-height:112px;padding:16px 18px;border-radius:20px;border:1px solid #e7ebf2;
      background:linear-gradient(160deg,rgba(234,239,252,0.72),rgba(248,249,254,0.96));
      display:flex;flex-direction:column;justify-content:space-between;
      cursor:${row.tj_app_id?'pointer':'default'};opacity:${row.tj_app_id?1:0.55}">
    <h4 style="margin:0;font-size:15px;font-weight:700;color:#2a3140">${row.name}</h4>
    <div style="color:#6b7486;font-size:12px">${(row.default_scope||[]).join(' · ')}</div>
  </article>`).join('');
return { html: `<div style="display:grid;grid-template-columns:repeat(3,1fr);gap:14px">${tiles}</div>` };
